# -- historical-copy reclamation --------------------------------------

def _parse_snapshot_name(self, name: str):
    """Parse a ``wal.s<seq>.<id>`` sidecar name; ``None`` if not one."""
    if not name.startswith(_SNAPSHOT_PREFIX):
        return None
    stem = name[len(_SNAPSHOT_PREFIX):]
    dot = stem.find(".")
    if dot <= 0:
        return None
    try:
        seq = int(stem[:dot])
        sid = bytes.fromhex(stem[dot + 1:])
    except ValueError:
        return None
    if seq < 1 or len(sid) != 32:
        return None
    return seq, sid

def _reclaim_snapshots(self) -> None:
    """Reclaim published snapshot copies that are neither used nor kept.

    A copy is kept when it is the current committed snapshot, when it is
    one of the newest ``_SNAPSHOT_RETENTION`` published copies, or when
    it is in use: an open cursor or a live read-only store in this
    process pins it. Every other ``wal.s<seq>.<id>`` sidecar is
    removed. Only redundant copies are deleted -- the log prefix and the
    checkpoint are untouched -- so ongoing reads and resumed scans do
    not change by a byte.

    The scan is idempotent and kill-safe: each unlink is independent,
    re-running reaches the same set of files, and a killed run is
    simply finished on the next open; malformed sidecar names are
    ignored rather than treated as files to delete.
    """
    current = self._seq
    copies = []  # (seq, sid, name)
    try:
        names = os.listdir(self._dir)
    except FileNotFoundError:
        return
    for name in names:
        parsed = self._parse_snapshot_name(name)
        if parsed is not None:
            copies.append((parsed[0], parsed[1], name))
    kept_seqs = {seq for seq, _sid, _n in
                 sorted(copies, reverse=True)[:_SNAPSHOT_RETENTION]}
    live = _live_snapshot_keys()
    for seq, sid, name in copies:
        if seq == current or seq in kept_seqs or (seq, sid) in live:
            continue
        try:
            os.unlink(os.path.join(self._dir, name))
        except FileNotFoundError:
            pass
    _fsync_dir(self._dir)

